    # 1 - (409) POST:/api/v2/variables
    # 2 - (409) POST:/api/v2/variables
    # 3 - (422) POST:/api/v2/variables
    # 4 - (422) POST:/api/v2/variables
    # 5 - (200) GET:/api/v2/variables
    # Found 1 potential fault of type-code 201
    @timeout_decorator.timeout(60)
    def test_4_get_on_variables_vulnerableToXSS(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"victim\", " + \
            " \"password\" : \"victimpass\" " + \
            " } "
        res_victim = requests \
                .post(self.baseUrlOfSut + "/auth/token", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_victim =  res_victim.json()["access_token"]
        
        auth_victim = "Bearer " + token_victim
        
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"key\" : \"BDY6CkQIuwX3xAo\", " + \
            " \"value\" : { " + \
            " \"Vy8fEv\" : \"KdP2nbUgPxLP\", " + \
            " \"MiRwCpVKn3Gibwb9\" : \"C\" " + \
            " } " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/v2/variables",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 409
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["detail"] == "The Variable with key: `BDY6CkQIuwX3xAo` already exists"
        
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"key\" : \"Dee\", " + \
            " \"value\" : { " + \
            " \"byvlcRdiStm5y\" : \"z2yfr4LB93li4b7\" " + \
            " } " + \
            " } "
        headers['Accept'] = "application/json"
        res_1 = requests \
                .post(self.baseUrlOfSut + "/api/v2/variables",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 409
        assert "application/json" in res_1.headers["content-type"]
        assert res_1.json()["detail"] == "The Variable with key: `Dee` already exists"
        
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"key\" : \"09lFeKa9FtI\", " + \
            " \"value\" : { " + \
            " \"97fKDO92v9kmF26p\" : \"1l66PjJPbXpcuF\", " + \
            " \"S7hFg7lagw\" : \"w7HwktQZolom84t8\", " + \
            " \"qTwJ8wcq_FDlij70\" : \"Csi\", " + \
            " \"iy5FCZNPGUhvQgZe\" : \"SW\" " + \
            " }, " + \
            " \"description\" : \"ODBC https://github.com/mkleehammer/pyodbc/wiki\", " + \
            " \"team_name\" : \"FKEFMRIbT1\" " + \
            " } "
        headers['Accept'] = "application/json"
        res_2 = requests \
                .post(self.baseUrlOfSut + "/api/v2/variables",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_2.status_code == 422
        assert "application/json" in res_2.headers["content-type"]
        assert len(res_2.json()["detail"]) == 1
        assert res_2.json()["detail"][0]["type"] == "value_error"
        assert len(res_2.json()["detail"][0]["loc"]) == 1
        assert res_2.json()["detail"][0]["loc"][0] == "body"
        assert res_2.json()["detail"][0]["msg"] == "Value error, team_name cannot be set when multi_team mode is disabled. Please contact your administrator."
        assert res_2.json()["detail"][0]["input"]["key"] == "09lFeKa9FtI"
        assert res_2.json()["detail"][0]["input"]["value"]["97fKDO92v9kmF26p"] == "1l66PjJPbXpcuF"
        assert res_2.json()["detail"][0]["input"]["value"]["S7hFg7lagw"] == "w7HwktQZolom84t8"
        assert res_2.json()["detail"][0]["input"]["value"]["qTwJ8wcq_FDlij70"] == "Csi"
        assert res_2.json()["detail"][0]["input"]["value"]["iy5FCZNPGUhvQgZe"] == "SW"
        assert res_2.json()["detail"][0]["input"]["description"] == "ODBC https://github.com/mkleehammer/pyodbc/wiki"
        assert res_2.json()["detail"][0]["input"]["team_name"] == "FKEFMRIbT1"
        assert len(res_2.json()["detail"][0]["ctx"]["error"]) == 0
        
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"key\" : \"tW\", " + \
            " \"value\" : { }, " + \
            " \"description\" : { " + \
            " \"AIFpb0Anvx\" : \"\", " + \
            " \"xa5rd3uYoHiVRSP\" : \"4jp\", " + \
            " \"4AzX0AEbO\" : \"jN9N01CK5bWg\", " + \
            " \"MpsrExNA_2\" : \"74Pn1Du4nn5Y\", " + \
            " \"\" : \"9\" " + \
            " } " + \
            " } "
        headers['Accept'] = "application/json"
        res_3 = requests \
                .post(self.baseUrlOfSut + "/api/v2/variables",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_3.status_code == 422
        assert "application/json" in res_3.headers["content-type"]
        assert len(res_3.json()["detail"]) == 1
        assert res_3.json()["detail"][0]["type"] == "string_type"
        assert len(res_3.json()["detail"][0]["loc"]) == 2
        assert res_3.json()["detail"][0]["loc"][0] == "body"
        assert res_3.json()["detail"][0]["loc"][1] == "description"
        assert res_3.json()["detail"][0]["msg"] == "Input should be a valid string"
        assert res_3.json()["detail"][0]["input"]["AIFpb0Anvx"] == ""
        assert res_3.json()["detail"][0]["input"]["xa5rd3uYoHiVRSP"] == "4jp"
        assert res_3.json()["detail"][0]["input"]["4AzX0AEbO"] == "jN9N01CK5bWg"
        assert res_3.json()["detail"][0]["input"]["MpsrExNA_2"] == "74Pn1Du4nn5Y"
        assert res_3.json()["detail"][0]["input"][""] == "9"
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers["Authorization"] = auth_victim # victim
        headers['Accept'] = "application/json"
        res_4 = requests \
                .get(self.baseUrlOfSut + "/api/v2/variables?" + 
                    "variable_key_pattern=%3Cimg+src%3Dx+onerror%3Dalert%28%27XSS%27%29%3E&" + 
                    "variable_key_prefix_pattern=%3Cimg+src%3Dx+onerror%3Dalert%28%27XSS%27%29%3E",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_4.status_code == 200
        assert "application/json" in res_4.headers["content-type"]
        assert len(res_4.json()["variables"]) == 1
        assert res_4.json()["variables"][0]["key"] == "<img src=x onerror=alert('XSS')>"
        assert res_4.json()["variables"][0]["value"] == "{\"4lVPpeJps\": \"2HonA0QQM09\", \"UWKyDybWnaD\": \"eB_e4nRF\"}"
        assert res_4.json()["variables"][0]["description"] == "<img src=x onerror=alert('XSS')>"
        assert res_4.json()["variables"][0]["is_encrypted"] == True
        assert res_4.json()["variables"][0]["team_name"] is None
        assert res_4.json()["total_entries"] == 1
    
    
